fit_end_n = fit.placed_at.max().normalize()
start_n = fit.placed_at.min().normalize()

def all_cands(sk):
    s=fit[fit.sku==sk]; out={}
    daily = s.groupby(s.placed_at.dt.normalize()).units.sum()
    full = daily.reindex(pd.date_range(s.placed_at.min().normalize(), fit_end_n), fill_value=0.0)
    full2 = daily.reindex(pd.date_range(start_n, fit_end_n), fill_value=0.0)
    out["u365"]=s.units.sum()/365.0
    for a in [0.05,0.1,0.15,0.2,0.25,0.3,0.4,0.5]:
        out["ewm%.2f_full"%a]=full.ewm(alpha=a).mean().iloc[-1]
        out["ewm%.2f_full2"%a]=full2.ewm(alpha=a).mean().iloc[-1]
    for w in [7,14,21,28,30,45,60,90]:
        out["roll%d"%w]=full.rolling(w,min_periods=1).mean().iloc[-1]
    return out

res={}
for sk,t in tg.items():
    c=all_cands(sk)
    for k,v in c.items():
        res.setdefault(k,[]).append(abs(v-t)/max(abs(t),1e-9))
rows=sorted([(1-np.mean(np.array(v)>0.001), np.median(v), k) for k,v in res.items()])
for r in rows[-12:]:
    print(r)
